step3_testbench.spice:
* ngspice testbench for Push-Pull Op-Amp
.lib ${SKY130_PDK} tt

* Define dummy parameters for the parameterized netlist to prevent errors
.param W_xm1=5u L_xm1=0.5u W_xm2=5u L_xm2=0.5u W_xm3=5u L_xm3=0.5u W_xm4=5u L_xm4=0.5u
.param W_xm5=5u L_xm5=0.5u W_xm6t=5u L_xm6t=0.5u W_xm6=5u L_xm6=0.5u W_xm7=5u L_xm7=0.5u
.param W_xm8=5u L_xm8=0.5u W_xm9=5u L_xm9=0.5u W_xm10=5u L_xm10=0.5u W_xm11=5u L_xm11=0.5u
.param W_xm12=5u L_xm12=0.5u W_xm13=5u L_xm13=0.5u W_xm14=5u L_xm14=0.5u W_xm15=5u L_xm15=0.5u
.param W_xmsu1=2u L_xmsu1=1u W_xmsu2=2u L_xmsu2=1u W_xmsu3=2u L_xmsu3=1u
.param W_xma3=2u L_xma3=1u W_xma4=2u L_xma4=1u

* Input Stimulus
* VDD is already defined in the DUT netlist as 'VDD VDD 0 1.8'
Vin Vin 0 dc 0.9 ac 1 pulse(0.4 1.4 10n 1n 1n 1u 2u)

* Include the DUT (Pasted directly as requested)
VDD VDD 0 1.8
xm2 fbr Vin N002 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
xm1 fbl out N002 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
xm4 out12 out11 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm4} l={L_xm4}
xm3 out11 out11 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm3} l={L_xm3}
xm6t N002 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm6t} l={L_xm6t}
X_U1 Vbiasn Vbiasp VDD 0 SUB_1
xm5 N002 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm5} l={L_xm5}
xm6 N001 Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm6} l={L_xm6}
xm7 N001 Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm7} l={L_xm7}
xm8 out12 Vin fbr 0 sky130_fd_pr__nfet_01v8 w={W_xm8} l={L_xm8}
xm9 out11 out fbl 0 sky130_fd_pr__nfet_01v8 w={W_xm9} l={L_xm9}
xm10 Out22 N003 0 0 sky130_fd_pr__nfet_01v8 w={W_xm10} l={L_xm10}
xm11 N003 N003 0 0 sky130_fd_pr__nfet_01v8 w={W_xm11} l={L_xm11}
xm12 N003 Out12 N001 VDD sky130_fd_pr__pfet_01v8 w={W_xm12} l={L_xm12}
xm13 Out22 Out11 N001 VDD sky130_fd_pr__pfet_01v8 w={W_xm13} l={L_xm13}
xm14 out Out22 0 0 sky130_fd_pr__nfet_01v8 w={W_xm14} l={L_xm14}
xm15 out Out12 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm15} l={L_xm15}
C1 out 0 1e-11
C2 out fbr 2.4e-13
C3 Out22 fbl 2.4e-13
.subckt SUB_1 Vbiasn Vbiasp VDD GND
  xmsu2 N002 N002 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xmsu2} l={L_xmsu2}
  xmsu1 N002 Vbiasn GND 0 sky130_fd_pr__nfet_01v8 w={W_xmsu1} l={L_xmsu1}
  xmsu3 Vbiasp N002 Vbiasn 0 sky130_fd_pr__nfet_01v8 w={W_xmsu3} l={L_xmsu3}
  xm3 Vbiasn Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm3} l={L_xm3}
  xm4 N003 Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm4} l={L_xm4}
  xm1 Vbiasn Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
  R1 N004 0 4k
  xma4 Vbiasp N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma4} l={L_xma4}
  xma3 N001 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma3} l={L_xma3}
  xm5 N001 N003 0 0 sky130_fd_pr__nfet_01v8 w={W_xm5} l={L_xm5}
  xm7 VDD Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm7} l={L_xm7}
  xm2 Vbiasp Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
  xm6 N003 N003 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm6} l={L_xm6}
.ends SUB_1

.control
* 1. DC Operating Point for Power
op
let power_dissipation = -i(VDD) * 1.8
print power_dissipation

* 2. AC Analysis for Closed-Loop Bandwidth (Unity Gain Freq approx)
ac dec 100 1 1G
let gain_db = vdb(out)
meas ac f_3db when gain_db=-3 fall=1
print f_3db

* 3. Transient Analysis for Slew Rate
tran 100p 2u
* Measure rising slew rate between 0.6V and 1.2V
meas tran t_rise trig v(out) val=0.6 rise=1 targ v(out) val=1.2 rise=1
let sr_rise_V_us = (1.2 - 0.6) / t_rise / 1e6
print sr_rise_V_us

* Measure falling slew rate between 1.2V and 0.6V
meas tran t_fall trig v(out) val=1.2 fall=1 targ v(out) val=0.6 fall=1
let sr_fall_V_us = (1.2 - 0.6) / t_fall / 1e6
print sr_fall_V_us

quit
.endc
.end

